-- ============================================================
--  Supabase SQL dump - Ubuntu Cultural Connect
--  Generated from SQLite data.db
--  Paste this entire file into the Supabase SQL Editor
-- ============================================================

BEGIN;

-- Clean slate (idempotent): safe to re-run this file any time
DROP TABLE IF EXISTS "experience_events", "itinerary_adds", "notifications", "travel_journals", "ratings", "trip_days", "trips", "user_preferences", "experiences", "users" CASCADE;
DROP TYPE IF EXISTS userrole CASCADE;
DROP TYPE IF EXISTS culturalcategory CASCADE;

DO $$ BEGIN
  CREATE TYPE userrole AS ENUM ('tourist', 'business_owner', 'admin');
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;

DO $$ BEGIN
  CREATE TYPE culturalcategory AS ENUM ('traditional_cooking', 'storytelling', 'music_dance', 'crafts', 'heritage_tours', 'township_life', 'rural_heritage', 'traditional_healing', 'textile_weaving', 'photography', 'nature_wildlife', 'accommodation');
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;


CREATE TABLE users (
	id SERIAL NOT NULL, 
	email VARCHAR NOT NULL, 
	hashed_password VARCHAR NOT NULL, 
	full_name VARCHAR NOT NULL, 
	phone_number VARCHAR, 
	role userrole NOT NULL, 
	visitor_type VARCHAR, 
	country VARCHAR, 
	is_verified BOOLEAN, 
	is_active BOOLEAN, 
	created_at TIMESTAMP WITHOUT TIME ZONE, 
	updated_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id)
)

;


CREATE TABLE experiences (
	id SERIAL NOT NULL, 
	title VARCHAR NOT NULL, 
	description TEXT NOT NULL, 
	category culturalcategory NOT NULL, 
	location VARCHAR NOT NULL, 
	province VARCHAR, 
	price FLOAT NOT NULL, 
	duration_hours FLOAT, 
	max_participants INTEGER, 
	image_url VARCHAR, 
	owner_id INTEGER NOT NULL, 
	is_active BOOLEAN, 
	is_approved BOOLEAN, 
	rejection_reason VARCHAR, 
	rejected_at TIMESTAMP WITHOUT TIME ZONE, 
	created_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(owner_id) REFERENCES users (id)
)

;


CREATE TABLE user_preferences (
	id SERIAL NOT NULL, 
	user_id INTEGER NOT NULL, 
	categories VARCHAR NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id), 
	UNIQUE (user_id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
)

;


CREATE TABLE trips (
	id SERIAL NOT NULL, 
	user_id INTEGER NOT NULL, 
	title VARCHAR NOT NULL, 
	destination VARCHAR NOT NULL, 
	start_date DATE NOT NULL, 
	end_date DATE NOT NULL, 
	notes TEXT, 
	created_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
)

;


CREATE TABLE trip_days (
	id SERIAL NOT NULL, 
	trip_id INTEGER NOT NULL, 
	day_number INTEGER NOT NULL, 
	date DATE NOT NULL, 
	activity VARCHAR NOT NULL, 
	experience_id INTEGER, 
	notes TEXT, 
	PRIMARY KEY (id), 
	FOREIGN KEY(trip_id) REFERENCES trips (id), 
	FOREIGN KEY(experience_id) REFERENCES experiences (id)
)

;


CREATE TABLE ratings (
	id SERIAL NOT NULL, 
	user_id INTEGER NOT NULL, 
	experience_id INTEGER NOT NULL, 
	score INTEGER NOT NULL, 
	comment TEXT, 
	is_approved BOOLEAN, 
	rejected_at TIMESTAMP WITHOUT TIME ZONE, 
	created_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(experience_id) REFERENCES experiences (id)
)

;


CREATE TABLE travel_journals (
	id SERIAL NOT NULL, 
	user_id INTEGER NOT NULL, 
	experience_id INTEGER, 
	title VARCHAR NOT NULL, 
	content TEXT NOT NULL, 
	location VARCHAR, 
	visit_date DATE, 
	mood VARCHAR, 
	created_at TIMESTAMP WITHOUT TIME ZONE, 
	updated_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(experience_id) REFERENCES experiences (id)
)

;


CREATE TABLE notifications (
	id SERIAL NOT NULL, 
	user_id INTEGER NOT NULL, 
	type VARCHAR NOT NULL, 
	message VARCHAR NOT NULL, 
	experience_id INTEGER, 
	tourist_name VARCHAR, 
	is_read BOOLEAN, 
	created_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(experience_id) REFERENCES experiences (id)
)

;


CREATE TABLE itinerary_adds (
	id SERIAL NOT NULL, 
	user_id INTEGER NOT NULL, 
	experience_id INTEGER NOT NULL, 
	trip_id INTEGER, 
	created_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(user_id) REFERENCES users (id), 
	FOREIGN KEY(experience_id) REFERENCES experiences (id), 
	FOREIGN KEY(trip_id) REFERENCES trips (id)
)

;


CREATE TABLE experience_events (
	id SERIAL NOT NULL, 
	experience_id INTEGER NOT NULL, 
	event_type VARCHAR NOT NULL, 
	user_id INTEGER, 
	created_at TIMESTAMP WITHOUT TIME ZONE, 
	PRIMARY KEY (id), 
	FOREIGN KEY(experience_id) REFERENCES experiences (id), 
	FOREIGN KEY(user_id) REFERENCES users (id)
)

;

COMMIT;

