-- experiences: 45 rows
INSERT INTO experiences ("id", "title", "description", "category", "location", "province", "price", "duration_hours", "max_participants", "image_url", "owner_id", "is_active", "is_approved", "rejection_reason", "rejected_at", "created_at") VALUES
  (6, 'uShaka Maritime Museum', 'Located at uShaka Marine World, this museum showcases the maritime history of Durban''s harbour with historic vessels, naval artifacts, and interactive exhibits.', 'heritage_tours', '1 King Shaka Ave, Point, Durban, 4001, KZN', 'KwaZulu-Natal', 80.0, 1.5, 30, '/img/hotspots/beach.jpg', 7, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762599'),
  (7, 'KwaMuhle Museum', 'Housed in the former Native Administration Department, this museum documents Durban''s apartheid history and the struggle for democracy with powerful exhibits.', 'heritage_tours', '130 Bram Fischer Rd, Durban, 4001, KZN', 'KwaZulu-Natal', 0.0, 1.5, 25, '/img/hotspots/museum.jpg', 8, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762601'),
  (8, 'Durban Natural Science Museum', 'Located in the Durban City Hall, this free museum features natural history exhibits including dinosaur fossils, taxidermy, and educational displays on southern African wildlife.', 'heritage_tours', 'City Hall, 1st Floor, Durban, 4001, KZN', 'KwaZulu-Natal', 0.0, 1.5, 30, '/img/hotspots/museum.jpg', 9, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762604'),
  (9, 'Bergtheil Museum', 'Set in a historic cotton plantation house in Westville, this museum tells the story of early German settlers and colonial life in the Durban area.', 'heritage_tours', '16 Flamingo Ave, Westville, 3630, KZN', 'KwaZulu-Natal', 10.0, 1.5, 20, '/img/hotspots/museum.jpg', 10, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762606'),
  (10, 'Natal Museum', 'Pietermaritzburg''s premier museum featuring natural science, cultural history, and a renowned collection of African art and artifacts spanning centuries.', 'heritage_tours', '237 Jabu Ndlovu St, Pietermaritzburg, 3201, KZN', 'KwaZulu-Natal', 20.0, 1.5, 25, '/img/hotspots/museum.jpg', 11, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762608'),
  (11, 'Kenneth Stainbank Nature Reserve', 'A coastal forest reserve in Yellowwood Park featuring walking trails, bird hides, and diverse wildlife including zebra, impala, and over 200 bird species.', 'nature_wildlife', 'Coedmore Rd, Yellowwood Park, Durban, 4001, KZN', 'KwaZulu-Natal', 20.0, 2.0, 20, '/img/hotspots/nature-forest.jpg', 12, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762610'),
  (12, 'Palmiet Nature Reserve', 'A 120-hectare reserve in Westville with trails along the Palmiet River, rich birdlife, and indigenous coastal forest perfect for nature walks and photography.', 'nature_wildlife', '10 Palmiet Rd, Westville, 3629, KZN', 'KwaZulu-Natal', 0.0, 2.0, 20, '/img/hotspots/nature-forest.jpg', 13, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762613'),
  (13, 'Umgeni River Birding Trail', 'A scenic birding trail along the Umgeni River in Durban, home to kingfishers, herons, fish eagles, and many other bird species in a tranquil riverine setting.', 'nature_wildlife', '603 The Ridge, Barcelona, Durban, 4001, KZN', 'KwaZulu-Natal', 0.0, 2.0, 15, '/img/hotspots/nature-forest.jpg', 14, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762615'),
  (14, 'Burman Bush Nature Reserve', 'A 40-hectare coastal forest reserve in Morningside, Durban with walking trails through indigenous bush, ideal for birdwatching and nature walks close to the city.', 'nature_wildlife', '152 Mariam Bee St, Morningside, Durban, 4001, KZN', 'KwaZulu-Natal', 0.0, 1.5, 15, '/img/hotspots/nature-forest.jpg', 15, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762617'),
  (15, 'Paradise Valley Nature Reserve', 'A 100-hectare reserve in New Germany featuring grasslands, forest trails, a river, and abundant birdlife — a peaceful escape into nature within the urban area.', 'nature_wildlife', '101 Paradise Rd, New Germany, 3610, KZN', 'KwaZulu-Natal', 0.0, 2.0, 20, '/img/hotspots/nature-forest.jpg', 16, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762620'),
  (16, 'Hluhluwe-iMfolozi Park — Hluhluwe Section', 'Africa''s oldest proclaimed nature reserve, this section offers exceptional game viewing of the Big Five in rolling hills of savannah and riverine forest.', 'nature_wildlife', 'Hluhluwe, 3960, KZN', 'KwaZulu-Natal', 120.0, 8.0, 15, '/img/hotspots/elephant.jpg', 17, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762622'),
  (17, 'Hluhluwe-iMfolozi Park — Memorial Gate', 'The main entrance to this world-renowned game reserve, offering self-drive safaris, guided game drives, and access to over 90,000 hectares of pristine African bush.', 'nature_wildlife', 'Hluhluwe, 3960, KZN', 'KwaZulu-Natal', 120.0, 8.0, 20, '/img/hotspots/elephant.jpg', 18, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762624'),
  (18, 'uMkhuze Game Reserve', 'A diverse reserve with wetlands, sand forest, and savannah, famous for its rhino population, birding hide, and ancient archaeological sites.', 'nature_wildlife', 'uMkhuze, 3960, KZN', 'KwaZulu-Natal', 120.0, 8.0, 15, '/img/hotspots/elephant.jpg', 19, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762626'),
  (19, 'iSimangaliso Wetland Park — Southern Section', 'A UNESCO World Heritage Site featuring Lake St Lucia, hippos, crocodiles, and prolific birdlife in Africa''s largest estuarine system.', 'nature_wildlife', 'St Lucia, 3936, KZN', 'KwaZulu-Natal', 200.0, 8.0, 20, '/img/hotspots/safari-sunset.jpg', 20, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762629'),
  (20, 'Mame Offers B&B', 'A warm and welcoming bed and breakfast in Manguzi offering comfortable rooms, traditional Zulu hospitality, and a home-cooked breakfast to start your day.', 'accommodation', 'P230, Manguzi, 3973, KZN', 'KwaZulu-Natal', 450.0, 8.0, 10, '/img/hotspots/lodge.jpg', 21, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762632'),
  (21, 'Manguzi Guest Lodge', 'A well-appointed guest lodge in Manguzi providing modern accommodation with en-suite rooms, a restaurant serving local cuisine, and easy access to nature reserves.', 'accommodation', 'P230, Manguzi, 3973, KZN', 'KwaZulu-Natal', 950.0, 8.0, 12, '/img/hotspots/lodge.jpg', 22, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762644'),
  (22, 'The Ndumo Wilderness Camp', 'An eco-lodge within the Ndumo Game Reserve offering luxury tented accommodation, guided game drives, and birding experiences in a pristine wilderness setting.', 'accommodation', 'Ndumo Game Reserve, 3973, KZN', 'KwaZulu-Natal', 1200.0, 8.0, 8, '/img/hotspots/lodge.jpg', 23, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762647'),
  (23, 'Shakaland Zulu Cultural Village Lodge', 'A renowned cultural lodge in Eshowe offering traditional Zulu beehive hut accommodation, spear-making demonstrations, and authentic Zulu dance and storytelling performances.', 'accommodation', 'R66, Eshowe, 3815, KZN', 'KwaZulu-Natal', 850.0, 8.0, 15, '/img/hotspots/lodge.jpg', 24, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762650'),
  (24, 'Emakhaya Lodge', 'A comfortable urban lodge in Durban offering stylish rooms, a swimming pool, and easy access to the city''s cultural attractions and beachfront.', 'accommodation', '34 Mbabane Rd, Durban, 4001, KZN', 'KwaZulu-Natal', 750.0, 8.0, 12, '/img/hotspots/lodge.jpg', 25, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762652'),
  (25, 'The Storytelling Circle Durban', 'A community storytelling gathering at Durban City Hall where local elders share folktales, oral histories, and Zulu legends passed down through generations.', 'storytelling', 'Durban City Hall, Durban, 4001, KZN', 'KwaZulu-Natal', 0.0, 2.0, 25, '/img/hotspots/storytelling.jpg', 26, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762655'),
  (26, 'Gogo''s Tales at Phansi Museum', 'Experience the magic of Gogo (grandmother) storytelling at the Phansi Museum, where traditional Zulu tales come alive with song, dance, and audience participation.', 'storytelling', '500 Roberts Rd, Glenwood, Durban, 4001, KZN', 'KwaZulu-Natal', 50.0, 1.5, 20, '/img/hotspots/storytelling.jpg', 2, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762657'),
  (27, 'African Storytelling Nights at The Bat Centre', 'An evening of African storytelling at Durban''s Bat Centre featuring professional storytellers, live music, and tales from Zulu, Xhosa, and other South African traditions.', 'storytelling', '45 Maritime Pl, Durban, 4001, KZN', 'KwaZulu-Natal', 80.0, 1.5, 30, '/img/hotspots/theatre.jpg', 3, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762659'),
  (28, 'Eshowe Cultural Storytelling Experience', 'An immersive storytelling experience in Eshowe where local elders share the history of the Zulu kingdom, Shaka''s legacy, and the traditions of King Cetshwayo''s people.', 'storytelling', '17 Main St, Eshowe, 3815, KZN', 'KwaZulu-Natal', 200.0, 2.5, 15, '/img/hotspots/storytelling.jpg', 4, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762662'),
  (29, 'Victoria Street Market', 'Durban''s iconic indoor market offering a vibrant array of African crafts, traditional clothing, beadwork, spices, and souvenirs in a historic building.', 'textile_weaving', '151 Victoria St, Durban, 4001, KZN', 'KwaZulu-Natal', 0.0, 2.0, 30, '/img/hotspots/market.jpg', 5, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762664'),
  (30, 'Muthi Traditional Market', 'Durban''s famous muthi (traditional medicine) market where sangomas and inyangas sell herbs, roots, and traditional remedies alongside cultural attire and artifacts.', 'textile_weaving', '14 Glass St, Durban, 4001, KZN', 'KwaZulu-Natal', 0.0, 2.0, 25, '/img/hotspots/market.jpg', 6, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762666'),
  (31, 'Inanda Craft & Design Centre', 'A community craft centre in Inanda showcasing Zulu pottery, weaving, beadwork, and traditional attire made by local artisans, supporting sustainable livelihoods.', 'textile_weaving', '200 Inanda Rd, Inanda, 4300, KZN', 'KwaZulu-Natal', 0.0, 2.0, 20, '/img/hotspots/crafts.jpg', 7, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762668'),
  (32, 'KwaMashu Craft Market', 'A vibrant township market in KwaMashu offering authentic Zulu crafts, traditional clothing, beaded jewelry, and home decor made by local community artisans.', 'textile_weaving', '12 KwaMashu Hwy, KwaMashu, 4013, KZN', 'KwaZulu-Natal', 0.0, 2.0, 25, '/img/hotspots/market.jpg', 8, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762671'),
  (33, 'Sangoma Consultation & Cultural Talk', 'An authentic sangoma consultation in Inanda where a traditional healer explains the calling process, divination using bones, and the role of ancestral spirits in healing.', 'traditional_healing', 'Inanda, 4300, KZN', 'KwaZulu-Natal', 250.0, 1.5, 5, '/img/hotspots/herbs.jpg', 9, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762673'),
  (34, 'Inyanga Traditional Healing Workshop', 'A hands-on workshop in KwaMashu where an inyanga (herbalist) demonstrates traditional medicine preparation, plant identification, and the spiritual philosophy of healing.', 'traditional_healing', '34 Muthi Ln, KwaMashu, 4013, KZN', 'KwaZulu-Natal', 300.0, 2.5, 8, '/img/hotspots/herbs.jpg', 10, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762675'),
  (35, 'Muthi Market & Healing Walk', 'A guided walk through Durban''s Muthi Market with a traditional healer who explains the medicinal uses of plants, roots, and herbs in Zulu traditional medicine.', 'traditional_healing', '14 Glass St, Durban, 4001, KZN', 'KwaZulu-Natal', 0.0, 2.0, 10, '/img/hotspots/market.jpg', 11, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762677'),
  (36, 'Zulu Herbal Remedy Workshop', 'Learn about the healing properties of indigenous KZN plants in this workshop led by a traditional healer who shares knowledge of herbal remedies passed down through families.', 'traditional_healing', '9 Plantation Rd, Durban, 4001, KZN', 'KwaZulu-Natal', 200.0, 2.0, 8, '/img/hotspots/herbs.jpg', 12, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762679'),
  (37, 'Nongoma Traditional Healing Village', 'Visit a traditional healing village in Nongoma where multiple sangomas practice ancestral healing, offering visitors insight into Zulu spiritual traditions and herbal medicine.', 'traditional_healing', '15 Sangoma St, Nongoma, 3950, KZN', 'KwaZulu-Natal', 350.0, 3.0, 8, '/img/hotspots/herbs.jpg', 13, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762681'),
  (38, 'The Old Fort', 'Durban''s oldest surviving building, built in 1837 by Voortrekkers, later used by British forces, now a heritage museum showcasing early colonial and military history.', 'heritage_tours', '71 Fort St, Durban, 4001, KZN', 'KwaZulu-Natal', 0.0, 1.0, 20, '/img/hotspots/church.jpg', 14, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762684'),
  (39, 'Durban City Hall', 'An architectural masterpiece built in 1910, housing the Natural Science Museum and art gallery, with beautiful Edwardian baroque design in the heart of the city.', 'heritage_tours', '150 Bram Fischer Rd, Durban, 4001, KZN', 'KwaZulu-Natal', 0.0, 1.5, 30, '/img/hotspots/church.jpg', 15, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762686'),
  (40, 'Emmanuel Cathedral', 'Durban''s historic Catholic cathedral built in 1904, featuring stunning Gothic revival architecture, stained glass windows, and a rich multicultural parish history.', 'heritage_tours', '44 Cathedral Rd, Durban, 4001, KZN', 'KwaZulu-Natal', 0.0, 1.0, 25, '/img/hotspots/church.jpg', 16, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762688'),
  (41, 'Juma Masjid Mosque', 'The largest mosque in the Southern Hemisphere, located in Durban''s Grey Street complex, featuring beautiful Islamic architecture and a rich history of the Indian Muslim community.', 'heritage_tours', '127 Grey St, Durban, 4001, KZN', 'KwaZulu-Natal', 0.0, 1.0, 25, '/img/hotspots/church.jpg', 17, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762690'),
  (42, 'The Playhouse Theatre', 'Durban''s premier performing arts venue hosting theatre productions, ballet, opera, and music concerts in a beautifully restored Edwardian building.', 'music_dance', '29 Acutt St, Durban, 4001, KZN', 'KwaZulu-Natal', 200.0, 2.5, 50, '/img/hotspots/theatre.jpg', 18, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762692'),
  (43, 'The Bat Centre', 'Durban''s vibrant waterfront arts centre showcasing African music, dance, theatre, and visual art in a dynamic creative space on the harbour edge.', 'music_dance', '45 Maritime Pl, Durban, 4001, KZN', 'KwaZulu-Natal', 75.0, 3.0, 40, '/img/hotspots/theatre.jpg', 19, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762694'),
  (44, 'Elizabeth Sneddon Theatre', 'A renowned theatre on the UKZN campus presenting cutting-edge drama, contemporary dance, and experimental performances by South Africa''s leading artists.', 'music_dance', '1 Lennox Rd, Durban, 4001, KZN', 'KwaZulu-Natal', 175.0, 2.5, 40, '/img/hotspots/theatre.jpg', 20, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762696'),
  (45, 'The Stable Theatre', 'A historic Durban theatre that was a gathering place for anti-apartheid activists, now hosting community theatre, poetry slams, and emerging local talent.', 'music_dance', '104 Warwick Ave, Durban, 4001, KZN', 'KwaZulu-Natal', 75.0, 2.0, 35, '/img/hotspots/theatre.jpg', 21, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762699'),
  (46, 'The Heritage Theatre', 'An intimate Durban theatre venue presenting plays, live music, comedy shows, and cultural performances celebrating South African storytelling and performing arts.', 'music_dance', '12 Heritage Ave, Durban, 4001, KZN', 'KwaZulu-Natal', 150.0, 2.5, 35, '/img/hotspots/theatre.jpg', 22, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762701'),
  (47, 'Inanda Heritage Route Tour', 'A full-day tour of Inanda''s rich heritage sites including the Gandhi Settlement, Ohlange Institute, and the Shembe Church''s holy village — a journey through South Africa''s liberation history.', 'heritage_tours', 'Inanda, 4300, KZN', 'KwaZulu-Natal', 350.0, 8.0, 12, '/img/hotspots/museum.jpg', 23, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762703'),
  (48, 'PheZulu Cultural Village & Safari', 'Experience Zulu culture at PheZulu Village with traditional dancing, homestead tours, and a game drive through the Valley of a Thousand Hills for wildlife viewing.', 'heritage_tours', '5 PheZulu Rd, Botha''s Hill, 3660, KZN', 'KwaZulu-Natal', 450.0, 8.0, 15, '/img/hotspots/cultural-dance.jpg', 24, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762705'),
  (49, 'The Zulu Experience', 'An authentic half-day immersion in Zulu culture in Eshowe, including traditional dancing, beadwork demonstrations, spear-making, and a taste of Zulu cuisine.', 'heritage_tours', '5 Mountain Dr, Eshowe, 3815, KZN', 'KwaZulu-Natal', 200.0, 4.0, 15, '/img/hotspots/cultural-dance.jpg', 25, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762707'),
  (50, 'Valley of a Thousand Hills Tour', 'A scenic full-day tour through the breathtaking Valley of a Thousand Hills with cultural stops, Zulu village visits, craft markets, and panoramic viewpoints.', 'heritage_tours', '10 Valley Rd, Hillcrest, 3610, KZN', 'KwaZulu-Natal', 300.0, 8.0, 15, '/img/hotspots/museum.jpg', 26, TRUE, TRUE, NULL, NULL, '2026-08-24 20:08:32.762709');

